{
  "items": [
    {
      "name": "finprod_mem_mulSupport",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} [inst : CommMonoid M] (f : α → M),\n  ∏ᶠ (a : α) (_ : a ∈ Function.mulSupport f), f a = ∏ᶠ (a : α), f a"
    },
    {
      "name": "tprod_eq_prod'",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : CommMonoid α] [inst_1 : TopologicalSpace α] {f : β → α} {L : SummationFilter β}\n  [L.LeAtTop] {s : Finset β}, Function.mulSupport f ⊆ ↑s → ∏'[L] (b : β), f b = ∏ b ∈ s, f b"
    },
    {
      "name": "finprod_mem_inter_mulSupport",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} [inst : CommMonoid M] (f : α → M) (s : Set α),\n  ∏ᶠ (i : α) (_ : i ∈ s ∩ Function.mulSupport f), f i = ∏ᶠ (i : α) (_ : i ∈ s), f i"
    },
    {
      "name": "Finsupp.multinomial",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "definition",
      "type": "{α : Type u_1} → (α →₀ ℕ) → ℕ"
    },
    {
      "name": "Finsupp.multinomial_eq_of_support_subset",
      "module_name": "Mathlib.Data.Nat.Choose.Multinomial",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {f : α →₀ ℕ} {s : Finset α}, f.support ⊆ s → f.multinomial = Nat.multinomial s ⇑f"
    }
  ]
}
